  {
   "id": "short_confidentiality_survival",
   "severity": "medium",
   "message": "Confidentiality obligations last only one year from each disclosure, so Northwind's sensitive information (including trade secrets) may be unprotected soon after. There is no carve-out for trade secrets.",
   "quote": "These obligations shall survive for one (1) years from the date of disclosure."
  },
  {
   "id": "no_term_or_termination_clause",
   "severity": "low",
   "message": "The agreement has no stated term or termination mechanism, yet the non-solicitation clause runs 'during the term', which makes its duration ambiguous.",
   "quote": "During the term and for twelve months thereafter, neither Party shall knowingly solicit for employment any Personnel of the other Party"
  },
  {
   "id": "mutual_audit_right",
   "severity": "low",
   "message": "Orchard may audit Northwind's records on notice, which could be intrusive for an NDA. The scope is limited to verifying compliance.",
   "quote": "a Party may audit the other Party's records solely to verify compliance with this Agreement"
  },
  {
   "id": "no_confidentiality_exclusions",
   "severity": "medium",
   "message": "The NDA has no definition of Confidential Information and no standard exclusions (public information, independently developed, and so on), which makes the scope uncertain.",
   "quote": "The Receiving Party shall hold the Disclosing Party's Confidential Information in strict confidence."
  }
 ],
